// A one-time code as separate boxes (SCREENS.md §1.18): 6 boxes, LTR in both languages, mono 22.
// filled = gold frame on an 8% gold ground · current = the caret box · empty = hairline on card.
// One hidden TextInput takes the keystrokes, so paste and the OS's SMS / one-time-code autofill
// work — boxes built from separate inputs break both.
export function OtpField({
  value,
  onChange,
  length = 6,
  onComplete,
  autoFocus = false,
  label,
}: {
  value: string;
  onChange: (v: string) => void;
  length?: number;
  /** Called once the last digit is in — e.g. to submit. */
  onComplete?: (v: string) => void;
  autoFocus?: boolean;
  label?: string;
}) {
  const c = useColors();
  const input = useRef<TextInput>(null);
  const [focused, setFocused] = useState(autoFocus);

  const set = (raw: string) => {
    const digits = raw.replace(/\D/g, '').slice(0, length);
    onChange(digits);
    if (digits.length === length) onComplete?.(digits);
  };

  return (
    <View style={{ gap: 8 }}>
      {label ? <AppText style={{ fontFamily: fonts.medium, fontSize: 11.5, color: c.muted }}>{label}</AppText> : null}
      {/* Codes read left to right in both languages: native via the direction style, web via dir. */}
      <Pressable accessibilityRole="none" onPress={() => input.current?.focus()} style={[styles.row, dirStyle(false)]} {...dirProps(false)}>
        {Array.from({ length }, (_, i) => {
          const filled = i < value.length;
          const current = focused && i === Math.min(value.length, length - 1) && !filled;
          return (
            <View
              key={i}
              style={[
                styles.box,
                filled
                  ? { borderColor: c.gold, backgroundColor: `${c.gold}14` }
                  : { borderColor: c.line, backgroundColor: c.card },
              ]}>
              {filled ? (
                <AppText style={{ fontFamily: fonts.mono, fontSize: 22, color: c.fg }}>{value[i]}</AppText>
              ) : current ? (
                <View style={{ width: 2, height: 24, backgroundColor: c.gold }} />
              ) : null}
            </View>
          );
        })}
      </Pressable>
      <TextInput
        ref={input}
        value={value}
        onChangeText={set}
        keyboardType="number-pad"
        textContentType="oneTimeCode"
        autoComplete="one-time-code"
        maxLength={length}
        autoFocus={autoFocus}
        onFocus={() => setFocused(true)}
        onBlur={() => setFocused(false)}
        caretHidden
        accessibilityLabel={label}
        style={styles.hidden}
      />
    </View>
  );
}

// Under the boxes: a clock and the time left at the start, "resend" at the end, live once the
// countdown ends (§02-4). `seconds` restarts the countdown whenever `restartKey` changes.
export function ResendCountdown({
  seconds,
  onResend,
  restartKey,
}: {
  seconds: number;
  onResend: () => void;
  restartKey?: unknown;
}) {
  const c = useColors();
  const t = useT();
  const [left, setLeft] = useState(seconds);

  useEffect(() => {
    setLeft(seconds);
    const id = setInterval(() => setLeft((s) => (s > 0 ? s - 1 : 0)), 1000);
    return () => clearInterval(id);
  }, [seconds, restartKey]);

  const mm = String(Math.floor(left / 60)).padStart(2, '0');
  const ss = String(left % 60).padStart(2, '0');
  const ready = left === 0;

  return (
    <View style={{ flexDirection: 'row', alignItems: 'center', gap: 10 }}>
      <View style={{ flex: 1, flexDirection: 'row', alignItems: 'center', gap: 7 }}>
        <Clock size={14} color={c.muted} strokeWidth={1.6} />
        <AppText style={{ fontFamily: fonts.mono, fontSize: 11.5, color: c.muted, writingDirection: 'ltr' }}>{`${mm}:${ss}`}</AppText>
      </View>
      <Pressable
        accessibilityRole="button"
        accessibilityState={{ disabled: !ready }}
        disabled={!ready}
        onPress={onResend}
        style={{ minHeight: metrics.touch, justifyContent: 'center' }}>
        <AppText style={{ fontFamily: fonts.regular, fontSize: 12.5, color: ready ? c.goldText : c.muted }}>{t('auth.resend')}</AppText>
      </Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  row: { flexDirection: 'row', gap: 9 },
  box: { flex: 1, minHeight: 56, borderRadius: metrics.radius.control, borderWidth: 1, alignItems: 'center', justifyContent: 'center' },
  // Off-screen but focusable and fillable; zero-size inputs lose autofill on some platforms.
  hidden: { position: 'absolute', opacity: 0, width: 1, height: 1 },
});
